unsigned patch_jump(void *insnbuf, const void *target, unsigned long addr, unsigned len)
{
    long offset;
    unsigned char *ip = insnbuf;

    if (len < 5) {
#ifdef CONFIG_RETPOLINE
        pr_warn("jump length too small for patching at %p\n", insnbuf);
#endif
        return len;
    }

    offset = (long)target - (long)(addr + 5);
    *(ip++) = 0xE9; /* jump opcode */
    *(ip++) = offset & 0xff;
    *(ip++) = (offset >> 8) & 0xff;
    *(ip++) = (offset >> 16) & 0xff;
    *ip = offset >> 24;

    return 5;
}

