unsigned patch_jump_insn(void *insnbuf, const void *target, unsigned long addr, unsigned len)
{
    unsigned int delta;

    if (len < 5) {
#ifdef CONFIG_RETPOLINE
        printk(KERN_WARNING "RETPOLINE: instruction buffer too small for jump patching\n");
#endif
        return len;
    }

    delta = (unsigned int)((unsigned long)target - addr - 5);

    *(unsigned char *)insnbuf = 0xE9; /* jmp rel32 */
    *(unsigned int *)((unsigned char *)insnbuf + 1) = delta;

    return 5;
}

